import{_ as t,o as a,c as s,a4 as i}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0054 — Les métadonnées des images sont retirées au dépôt, sans perte ni dépendance","description":"Extrait de docs/adr/0054-metadonnees-des-images-retirees-au-depot.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0054 — Les métadonnées des images sont retirées au dépôt, sans perte ni dépendance","description":"Extrait de docs/adr/0054-metadonnees-des-images-retirees-au-depot.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0054-metadonnees-des-images-retirees-au-depot.md","filePath":"developpeurs/adr/0054-metadonnees-des-images-retirees-au-depot.md"}'),n={name:"developpeurs/adr/0054-metadonnees-des-images-retirees-au-depot.md"};function o(r,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0054--les-métadonnées-des-images-sont-retirées-au-dépôt-sans-perte-ni-dépendance" tabindex="-1">ADR-0054 — Les métadonnées des images sont retirées au dépôt, sans perte ni dépendance <a class="header-anchor" href="#adr-0054--les-métadonnées-des-images-sont-retirées-au-dépôt-sans-perte-ni-dépendance" aria-label="Permalink to &quot;ADR-0054 — Les métadonnées des images sont retirées au dépôt, sans perte ni dépendance {#adr-0054--les-métadonnées-des-images-sont-retirées-au-dépôt-sans-perte-ni-dépendance}&quot;">​</a></h1><p><strong>Date :</strong> 26 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat RGPD-4 (moyen) ; complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a> sans en changer la décision n°4 (« aucune miniature, aucune dépendance »)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Une photo prise au téléphone porte des métadonnées : la position GPS de la prise de vue, la date, l&#39;appareil et parfois son numéro de série, le nom de l&#39;auteur, un logiciel, une vignette de l&#39;image d&#39;origine avant recadrage. La médiathèque gardait l&#39;original tel quel et le servait au public (<code>/api/v1/public/media/{id}/file</code>). Un agent qui publie une photo prise chez lui publie aussi son adresse.</p><p>L&#39;ADR-0041 exclut Pillow et toute retouche de l&#39;image : l&#39;original est gardé seul.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Au dépôt, avant l&#39;antivirus et avant la promotion</strong>, une image JPEG, PNG, WebP ou GIF perd toutes ses métadonnées : EXIF, XMP, IPTC, commentaires, textes et date PNG, vignette JFXX, images multiples MPF, blocs inconnus. Rien n&#39;est jamais écrit sous la clé du média avec elles.</li><li><strong>Restent, et seuls</strong> : <ul><li>les données de l&#39;image, <strong>recopiées octet pour octet</strong>, sans décodage ni recompression ;</li><li>le <strong>profil de couleur</strong>, sans lequel les couleurs d&#39;une photo changent ;</li><li>l&#39;<strong>orientation</strong>, seule dans un bloc EXIF réécrit, et seulement si elle n&#39;est pas « normale », pour qu&#39;une photo prise téléphone tourné s&#39;affiche droite ;</li><li>ce que le rendu exige (tables JPEG, <code>APP14 Adobe</code>, transparence et gamma PNG, animation APNG, WebP et GIF).</li></ul></li><li><strong>Sans dépendance</strong> : <code>app/media/metadata.py</code> lit la structure du fichier (en-têtes et longueurs), produit un plan de copie, et le dépôt l&#39;exécute en flux vers un nouveau temporaire. La mémoire ne dépend pas de la taille de l&#39;image. La ligne du média porte la taille et l&#39;empreinte (<code>ETag</code>) du fichier nettoyé.</li><li><strong>Une image dont la structure ne se lit pas est gardée telle quelle</strong>, sans refus : son type réel a déjà été confirmé, et une photo d&#39;appareil est bien formée.</li><li><strong>Le SVG n&#39;est pas traité</strong> : c&#39;est un texte écrit par son auteur, qui ne porte ni position ni appareil.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Pillow : décoder, tourner les pixels, réencoder</strong></td><td>Contraire à l&#39;ADR-0041 (dépendance native), et un JPEG réencodé perd en qualité à chaque dépôt.</td></tr><tr><td><strong>Ne retirer que la position GPS</strong></td><td>L&#39;appareil, son numéro de série, l&#39;auteur et la vignette d&#39;origine identifient aussi une personne ou révèlent ce que le recadrage cachait.</td></tr><tr><td><strong>Retirer aussi l&#39;orientation</strong></td><td>Une photo de téléphone s&#39;afficherait couchée, et l&#39;agent la re-déposerait sans comprendre pourquoi.</td></tr><tr><td><strong>Nettoyer au moment de servir</strong></td><td>Le fichier stocké garderait la position, et chaque lecture coûterait un nettoyage.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Aucune photo publiée ne révèle plus le lieu de la prise de vue ni l&#39;appareil.</li><li>Les images déposées ne perdent rien en qualité.</li></ul><p><strong>Négatives</strong></p><ul><li>Les images déposées <strong>avant</strong> ce correctif gardent leurs métadonnées : elles ne sont pas réécrites (voir l&#39;action ouverte).</li><li>Le droit d&#39;auteur inscrit dans l&#39;EXIF (<code>Copyright</code>) disparaît aussi. Le champ <code>copyright</code> du média, saisi par l&#39;agent, reste la seule mention qui fait foi.</li><li>Les pièces jointes des formulaires publics ne passent pas par ce chemin : ce sont des fichiers liés à une personne, jamais servis au public (ADR-0017).</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Retrait au dépôt des métadonnées des images de la médiathèque — <code>app/media/metadata.py</code>, <code>app/media/upload.py</code> (<code>_strip_image_metadata</code>, appelé par <code>finalize_media</code>) ; tests <code>tests/test_mediatheque_metadonnees.py</code>.</li><li>[x] Nettoyer les images déjà déposées : une tâche ou une commande qui réécrit chaque image, met à jour sa taille et son empreinte, et le dit dans son journal — commande <code>manage.py strip-media-metadata</code> / <code>python -m app.cli.media_metadata</code> (<code>--dry-run</code>, <code>--organization-id</code>), <code>app/cli/media_metadata.py</code>, primitive <code>MediaStore.open_stored</code> (<code>app/storage/media_files.py</code>), copie partagée avec le dépôt (<code>write_stripped_copy</code>, <code>app/media/upload.py</code>) ; tests <code>tests/test_nettoyage_des_images_deposees.py</code>.</li></ul>',16)])])}const g=t(n,[["render",o]]);export{m as __pageData,g as default};
